import{_ as n,a0 as o,w as p,s as d,ao as r,I as l,x as e,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"7 个好玩的 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"7 个好玩的 Linux 命令 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"7 个好玩的 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"7 个好玩的 Linux 命令 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211111 7 Linux commands to use just for fun","title":"7 个好玩的 Linux 命令","tag":"202111","desc":""},"relativePath":"202111/20211111 7 Linux commands to use just for fun.md","filePath":"[post].md"}'),h={name:"202111/20211111 7 Linux commands to use just for fun.md"};function c(u,s,g,k,b,f){const a=o("Link");return p(),d("div",null,[s[15]||(s[15]=r(`<h1 id="_7-个好玩的-linux-命令" tabindex="-1">7 个好玩的 Linux 命令 <a class="header-anchor" href="#_7-个好玩的-linux-命令" aria-label="Permalink to “7 个好玩的 Linux 命令”">​</a></h1><blockquote><p>这些好玩的 Linux 命令也有它的用处。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/16/164838m35s5q81t353sxq3.jpg" alt=""></p><p>Linux 的命令行可以说是资深用户和系统管理员的小窝。然而，Linux 不仅仅是大量的枯燥工作。Linux 是由爱玩的人开发的，他们还创造了一系列搞笑的命令。当你想轻松一下的时候，就可以自己试着这些。</p><h3 id="蒸汽机车" tabindex="-1">蒸汽机车 <a class="header-anchor" href="#蒸汽机车" aria-label="Permalink to “蒸汽机车”">​</a></h3><p>随便什么时候，你可以使用 <code>sl</code> 命令使一辆<ruby>蒸汽机车<rt>Steam Locomotive</rt></ruby>在你的终端上跑过。可以用你的软件包管理器安装这辆蒸汽机车。例如，在 Fedora 上可以这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install sl</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/locomotive_0.png" alt="由符号和字符组成的蒸汽机车引擎图" title="Steam locomotive"></p><h4 id="实际用途" tabindex="-1">实际用途 <a class="header-anchor" href="#实际用途" aria-label="Permalink to “实际用途”">​</a></h4><p>据我所知，<code>sl</code> 命令确实只是为了好玩。你对 <code>sl</code> 有什么有趣的用途吗？请在评论中告诉我。</p><p>（LCTT 译注：<code>sl</code> 的实际用途就是提醒你 <code>ls</code> 打错了。🤣）</p><h3 id="壁炉" tabindex="-1">壁炉 <a class="header-anchor" href="#壁炉" aria-label="Permalink to “壁炉”">​</a></h3><p>点燃一座壁炉来温暖你的心和你的终端吧，<code>aafire</code> 命令会播放一段壁炉的动画。你可以用你的软件包管理器安装 <code>aafire</code>。在 Debian、Mint、 Elementary 之类的发行版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install libaa-bin</span></span></code></pre></div><p>在 Fedora、CentOS 之类的发行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install aalib</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/fireside.png" alt="由文字符号和字符组成的火的黑白图像" title="fireside"></p><h4 id="实际用途-1" tabindex="-1">实际用途 <a class="header-anchor" href="#实际用途-1" aria-label="Permalink to “实际用途”">​</a></h4><p>这个动画是向你的团队或老板传达一切即将化为乌有的微妙方式。</p><h3 id="是的" tabindex="-1">是的 <a class="header-anchor" href="#是的" aria-label="Permalink to “是的”">​</a></h3><p>你可以使用 <code>yes</code> 命令打印出一串文字，直到用 <code>Ctrl+C</code> 强行停止。例如，我是一个 Buffalo Bills 的球迷，所以我选择用 <code>yes</code> 命令打印出一串无尽的 “Buffalo Bills”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yes Buffalo Bills</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/bills.png" alt="画面上重复显示的是一行行 Buffalo Bills（左侧边缘略微被切断）" title="Yes command"></p><h4 id="实际用途-2" tabindex="-1">实际用途 <a class="header-anchor" href="#实际用途-2" aria-label="Permalink to “实际用途”">​</a></h4><p>你可以用这个命令来向脚本输送确认信息，这样，当脚本停顿下来要求确认时，它就会自动收到 <code>yes</code>。例如，想象一下，你运行的一个脚本经常停下来问你确认：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ foo</span></span>
<span class="line"><span>Are you sure you want to do this? Y/n  Y</span></span>
<span class="line"><span>Are you really sure? y/N  Y</span></span>
<span class="line"><span>But are you really? y/N</span></span></code></pre></div><p>你可以通过向命令传递 <code>yes</code> 来自动接受这些信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yes | foo</span></span></code></pre></div><p>另外，你也可以用 <code>yes</code> 来自动拒绝信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yes no | foo</span></span></code></pre></div><h3 id="命运" tabindex="-1">命运 <a class="header-anchor" href="#命运" aria-label="Permalink to “命运”">​</a></h3><p>通过安装 <code>fortune</code> 命令，你可以就可以得到命运的指点。<code>fortune</code> 会打印出一段随机的、可能有意义的话语（LCTT 译注：来自命运的指点）。</p><p>用你的软件包管理器安装 <code>fortune</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install fortune</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install fortune-mod</span></span></code></pre></div><p>命运命令有许多数据集，它可以从中提取各种话语。例如，你可以从文学作品或科幻电视节目 《Firefly》中获得名人名言，或者从笑话、关于 Linux 的技巧等中选择。在你的资源库中搜索 <code>fortune</code>，看看你的发行版提供了哪些数据集。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fortune</span></span>
<span class="line"><span>Johnson&#39;s law:</span></span>
<span class="line"><span>  Systems resemble the organizations that create them.</span></span></code></pre></div><h4 id="实际用途-3" tabindex="-1">实际用途 <a class="header-anchor" href="#实际用途-3" aria-label="Permalink to “实际用途”">​</a></h4><p>你可以用命运来生成一个伪随机数。没有足够的熵来使它在密码学上安全，但当你需要一个意外的数字时，你可以用来计算字符或单词：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fortune | wc --chars</span></span>
<span class="line"><span>38</span></span>
<span class="line"><span>$ fortune | wc --words</span></span>
<span class="line"><span>8</span></span>
<span class="line"><span>$ fortune | wc --chars</span></span>
<span class="line"><span>169</span></span></code></pre></div><h3 id="彩虹猫" tabindex="-1">彩虹猫 <a class="header-anchor" href="#彩虹猫" aria-label="Permalink to “彩虹猫”">​</a></h3><p>彩虹猫（<code>lolcat</code>）是一个将文件或标准输入连接到标准输出的程序（就像一般的 <code>cat</code> 命令），并在其中加入彩虹色。你可以用管道将其他命令的输出连接到 <code>lolcat</code>，这样就可以为结果加上彩虹色。</p><p>下面是 <code>lolcat -h</code> 的帮助输出的结果。</p><p><img src="https://opensource.com/sites/default/files/uploads/lolcat_rainbow.png" alt="屏幕上的文字被染成了彩虹的渐变色" title="lolcat"></p><p>（LCTT 译注：我知道 <code>cat</code> 是 <code>catch</code>。）</p><h3 id="fig-来信-和横幅" tabindex="-1">“FIG 来信”和横幅 <a class="header-anchor" href="#fig-来信-和横幅" aria-label="Permalink to ““FIG 来信”和横幅”">​</a></h3><p>“FIG 来信”（FIGlet）来源于 Frank、Ian 和 Glenn 信件中的签名艺术。这个命令（<code>figlet</code>）和横幅命令（<code>banner</code>）可以帮你创建简单的 ASCII 文本横幅。下面是一个 CentOS 系统的文本横幅：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ figlet centos.com</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/figlet_centos.png" alt="由符号和字符组成的阅读 “centos.com” 的文本横幅" title="figlet text banner"></p><p>将 <code>figlet</code> 连接到 <code>lolcat</code>，可以得到一个彩色的横幅：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ figlet centos.com | lolcat</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/lolcat_figlet_centos.png" alt="用 lolcat 将 “centos.com” 的文字横幅渲染成彩虹色" title="Figlet with lolcat effects"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ banner Hello World</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/hello_world_0.png" alt="用英镑符号拼出的 “Hello World” 横幅" title="Hello World banner"></p><h4 id="实际用途-4" tabindex="-1">实际用途 <a class="header-anchor" href="#实际用途-4" aria-label="Permalink to “实际用途”">​</a></h4><p><code>figlet</code> 和 <code>banner</code> 都是提醒用户他们正在登录的系统的简单方法。就像许多系统管理员、网页设计师和云开发人员一样，当你和几十台服务器一起工作时，这很有帮助。</p><h3 id="电子语音" tabindex="-1">电子语音 <a class="header-anchor" href="#电子语音" aria-label="Permalink to “电子语音”">​</a></h3><p>你可以通过安装电子语音（<code>espeak</code>）来为你的命令行添加语音功能。</p><p>一旦 <code>espeak</code> 安装完毕，调高你的电脑的音量，听你的机器和你说话，会有一些乐趣。电子语音是一个软件语音合成器，有几个不同的语音库可用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ espeak &quot;Linux is the best operating system.”</span></span></code></pre></div><h3 id="有趣的命令" tabindex="-1">有趣的命令 <a class="header-anchor" href="#有趣的命令" aria-label="Permalink to “有趣的命令”">​</a></h3><p>请查阅所有这些命令的手册，以探索所有的可能性和变化。你最喜欢哪些好玩的命令，它们在现实世界中是否也有用途？请在评论中分享你的最爱。</p><hr>`,64)),l("p",null,[s[1]||(s[1]=e("via: ",-1)),i(a,{href:"https://opensource.com/article/21/11/fun-linux-commands"},{default:t(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/21/11/fun-linux-commands",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=e("作者：",-1)),i(a,{href:"https://opensource.com/users/don-watkins"},{default:t(()=>[...s[2]||(s[2]=[e("Don Watkins",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const C=n(h,[["render",c]]);export{x as __pageData,C as default};
